class PanelQuad;
class PanelGeom {
public:
    stringx name;
    matrix4x4 matrix;
    char pad[28];
    PanelGeom *children;
    PanelGeom *next;
    PanelGeom *parent;
    virtual ~PanelGeom();
    virtual int Kind() const;
    virtual bool Load(unsigned char *, int &);
    virtual void Reload();
    virtual PanelGeom *FindObject(const stringx &);
    virtual PanelQuad *GetQuad();
    virtual void Init(PanelQuad **, bool = false);
    virtual void Init(PanelQuad **, matrix4x4, bool = false);
};
class PanelBatch {
public:
    char data[100];
    void Init(PanelQuad **, stringx, matrix4x4, bool);
};
class PanelObject : public PanelGeom {
public:
    char pad[12];
    unsigned short size;
    unsigned short nbatches;
    PanelBatch *batches;
    virtual void Init(PanelQuad **, matrix4x4, bool = false);
};

void PanelObject::Init(PanelQuad** pquads, matrix4x4 parent_matrix, bool floating)
{
	matrix4x4 this_matrix = parent_matrix*matrix;
	for(int i=0; i<nbatches; i++)
		batches[i].Init(pquads, name, this_matrix, floating);
	if(children)
		children->Init(pquads, this_matrix, floating);
}
